components.css:
.action { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 36px; padding: 8px 14px; border: 1px solid transparent; border-radius: 7px; background: var(--primary, #166348); color: #fff; font-family: 'Inter Variable', sans-serif; font-size: 13px; line-height: 18px; font-weight: 500; cursor: pointer; transition: background-color 0.13s, border-color 0.13s; }
.action:hover { background: #104f38; }
.action:focus-visible { outline: 2px solid #278061; outline-offset: 3px; }
.action:disabled { opacity: 0.55; cursor: not-allowed; }
@media (max-width: 700px) { .action { min-height: 44px; } }
@media (prefers-reduced-motion: reduce) { .action { transition: none; } }

.field { display: flex; flex-direction: column; gap: 7px; margin-bottom: 17px; color: var(--text, #202a24); font-family: 'Inter Variable', sans-serif; font-size: 13px; font-weight: 500; }
.field input { padding: 8px 10px; border: 1px solid var(--control, #ccd5cf); border-radius: 7px; background: #fff; color: var(--text, #202a24); font-family: inherit; font-size: 13px; font-weight: 400; caret-color: var(--primary, #166348); }
.field input::placeholder { color: #6b756e; }
.field input:focus-visible { outline: 2px solid #278061; outline-offset: 3px; }

.nav { display: flex; align-items: center; gap: 10px; min-height: 35px; margin: 2px 0; padding: 8px 12px; border-radius: 7px; background: #e0e9e3; color: #145b40; font-family: 'Inter Variable', sans-serif; font-size: 14px; line-height: 18px; font-weight: 550; text-decoration: none; }
.nav:hover { background: #e9efeb; }
.nav:focus-visible { outline: 2px solid #278061; outline-offset: 3px; }
